{"cmd": "call_mcp() {
  local endpoint=$1 tool=$2 command=$3
  jq -nc --arg tool "$tool" --arg command "$command" '{jsonrpc:"2.0",id:2,method:"tools/call",params:{name:$tool,arguments:{command:$command}}}' |
    curl -sS --max-time 30 -H 'Content-Type: application/json' -H 'Accept: application/json, text/event-stream' --data-binary @- "http://localhost:3001/mcp/$endpoint" |
    jq -r '.result.content[]?.text // .error.message // .'
}
call_mcp bash_tools_for_target_and_defaults default 'printf "tool=default cwd="; pwd; printf "target=%s\n" "${CYBERGYM_TARGET_BINARY-<unset>}"; uname -a'
printf '\n'
